using System.Text.Json;
using DotReticulum.Core;

namespace DotLXST.Tests;

/// <summary>Generated by executing LXST 0.4.5 SHA 3b596f48ddd252ddc9c315ef8f3020cfd3688223.</summary>
[Trait("Category", "Unit")]
public sealed class StreamPacketTests
{
    [Fact]
    public void ActualUpstreamPacketizerAndSignallingBytesMatch()
    {
        using var fixture = LoadVectors();
        foreach (var vector in fixture.RootElement.GetProperty("packets").EnumerateArray())
        {
            var bytes = Convert.FromHexString(vector.GetProperty("encoded").GetString()!);
            var packet = StreamPacket.Decode(bytes);
            if (vector.GetProperty("kind").GetString() == "signal")
                Assert.Equal(vector.GetProperty("signal").GetInt64(), Assert.Single(packet.Signals));
            else Assert.Equal(CodecKind.Raw, Assert.Single(packet.Frames).Codec);
            Assert.Equal(bytes, packet.Encode());
        }
    }

    [Fact]
    public void MultipleFramesCombinedWithScalarSignalAndUnknownField()
    {
        var bytes = MsgPack.Pack(new Dictionary<object, object?>
        {
            [0L] = 4L,
            [1L] = new object?[] { new byte[] { 0, 0 }, new byte[] { 1, 0xfc } },
            [2L] = "extension",
        });
        var packet = StreamPacket.Decode(bytes);
        Assert.Equal(4, Assert.Single(packet.Signals));
        Assert.Equal(2, packet.Frames.Count);
        Assert.Equal(CodecKind.Opus, packet.Frames[1].Codec);
    }

    [Theory]
    [InlineData("90")]
    [InlineData("8101c400")]
    [InlineData("8101c40103")]
    [InlineData("8100a178")]
    [InlineData("8101c4020000ff")]
    public void RejectsMalformedEnvelope(string encoded) =>
        Assert.Throws<FormatException>(() => StreamPacket.Decode(Convert.FromHexString(encoded)));

    [Fact]
    public void EnforcesByteAndContainerLimits()
    {
        Assert.Throws<FormatException>(() => StreamPacket.Decode(new byte[StreamPacket.MaximumEncodedBytes + 1]));
        var frames = Enumerable.Range(0, 257).Select(_ => new EncodedFrame(CodecKind.Raw, new byte[] { 0 })).ToArray();
        Assert.Throws<ArgumentException>(() => new StreamPacket { Frames = frames }.Encode());
    }

    [Fact]
    public void RawSamplesMatchExecutedReferenceAcrossDepthsAndChannels()
    {
        using var fixture = LoadVectors();
        foreach (var vector in fixture.RootElement.GetProperty("raw").EnumerateArray())
        {
            using var codec = new RawAudioCodec(vector.GetProperty("bits").GetInt32(), vector.GetProperty("channels").GetInt32());
            var samples = vector.GetProperty("input").EnumerateArray().Select(v => v.GetSingle()).ToArray();
            var encoded = codec.Encode(new(samples, 48_000, 2));
            Assert.Equal(Convert.FromHexString(vector.GetProperty("encoded").GetString()!), encoded);
            var decoded = codec.Decode(encoded);
            Assert.Equal(vector.GetProperty("decoded").EnumerateArray().Select(v => v.GetSingle()), decoded.Samples.ToArray());
        }
    }

    [Theory]
    [InlineData("")]
    [InlineData("200000")]
    [InlineData("0100")]
    public void RawRejectsTruncationOrExcessiveChannels(string bytes) =>
        Assert.Throws<FormatException>(() => new RawAudioCodec().Decode(Convert.FromHexString(bytes)));

    [Fact]
    public void Float128IsExplicitlyUnsupported() =>
        Assert.Throws<NotSupportedException>(() => new RawAudioCodec().Decode([0xc0]));

    internal static JsonDocument LoadVectors() =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Fixtures", "lxst-vectors.json")));
}
